/**
 * Health check method wrappers
 *
 * @module @vreko/local-service-client/methods/health
 */

import type { HealthCheckParamsType, LocalServiceMethod } from "../types.js";

/**
 * Function signature for making JSON-RPC calls
 */
export type CallFn = <TResult = unknown>(method: LocalServiceMethod, params?: unknown) => Promise<TResult>;

/**
 * Health check response
 */
export interface HealthCheckResponse {
	/** Service is healthy and accepting requests */
	healthy: boolean;
	/** Service uptime in seconds */
	uptime: number;
	/** Active connections count */
	connections: number;
	/** Service version */
	version?: string;
	/** How the daemon is supervised. Added in HealthCheckResponseV2 (contracts). */
	supervisorMode?: "launchd" | "systemd" | "extension" | "none";
	/** Additional diagnostic information (if verbose=true) */
	diagnostics?: {
		/** Memory usage in bytes */
		memoryUsage: number;
		/** CPU usage percentage */
		cpuUsage: number;
		/** Active sessions count */
		activeSessions: number;
		/** Total snapshots count */
		totalSnapshots: number;
	};
}

/**
 * Ping response
 */
export interface HealthPingResponse {
	/** Server response ("pong") */
	message: "pong";
	/** Server timestamp in milliseconds */
	timestamp: number;
}

/**
 * Health methods namespace
 */
export interface HealthMethods {
	/**
	 * Check service health status
	 */
	check(params?: HealthCheckParamsType): Promise<HealthCheckResponse>;

	/**
	 * Simple ping to verify service is responsive
	 */
	ping(): Promise<HealthPingResponse>;
}

/**
 * Create health methods namespace
 */
export function createHealthMethods(call: CallFn): HealthMethods {
	return {
		check: (params) => call<HealthCheckResponse>("health/check", params),
		ping: () => call<HealthPingResponse>("health/ping"),
	};
}
