/**
 * Validation method wrappers
 *
 * @module @vreko/local-service-client/methods/validation
 */

import type { ValidateComprehensiveParamsType, ValidateQuickParamsType } from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface ValidateQuickResponse {
	passed: boolean;
	checks: {
		typescript: { passed: boolean; errors: number };
		lint: { passed: boolean; errors: number };
		tests: { passed: boolean; errors: number };
	};
	fileCount: number;
	duration: number;
}

export interface ValidateComprehensiveResponse {
	passed: boolean;
	confidence: number;
	totalIssues: number;
	recommendation: string;
	focusPoints: unknown[];
	layers: unknown[];
}

export interface ValidationMethods {
	quick(params: ValidateQuickParamsType): Promise<ValidateQuickResponse>;
	comprehensive(params: ValidateComprehensiveParamsType): Promise<ValidateComprehensiveResponse>;
}

export function createValidationMethods(call: CallFn): ValidationMethods {
	return {
		quick: (params) => call<ValidateQuickResponse>("validate/quick", params),
		comprehensive: (params) => call<ValidateComprehensiveResponse>("validate/comprehensive", params),
	};
}
