/**
 * MCP coordination method wrappers
 *
 * @module @vreko/local-service-client/methods/mcp
 */

import type { MCPFileModifiedParamsType, MCPSnapshotCreatedParamsType } from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface MCPAcknowledgeResponse {
	acknowledged: boolean;
}

export interface MCPMethods {
	snapshotCreated(params: MCPSnapshotCreatedParamsType): Promise<MCPAcknowledgeResponse>;
	fileModified(params: MCPFileModifiedParamsType): Promise<MCPAcknowledgeResponse>;
}

export function createMCPMethods(call: CallFn): MCPMethods {
	return {
		snapshotCreated: (params) => call<MCPAcknowledgeResponse>("mcp/snapshot-created", params),
		fileModified: (params) => call<MCPAcknowledgeResponse>("mcp/file-modified", params),
	};
}
