/**
 * Supervisor method wrappers
 *
 * @module @vreko/local-service-client/methods/supervisor
 */

import type {
	SupervisorHeartbeatParamsType,
	SupervisorRegisterParamsType,
	SystemHealthParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface SupervisorRegisterResponse {
	registered: boolean;
	pid: number;
	type: string;
}

export interface SupervisorHeartbeatResponse {
	acknowledged: boolean;
	error?: string;
}

export interface SystemHealthResponse {
	status: string;
	uptime: number;
	workspaces: number;
	activeSessions: number;
	supervisedComponents: number;
	memory?: { heapUsed: number; heapTotal: number; rss: number };
	components?: Array<{ pid: number; type: string; lastHeartbeat: string; workspace: string }>;
}

export interface SupervisorMethods {
	register(params: SupervisorRegisterParamsType): Promise<SupervisorRegisterResponse>;
	heartbeat(params: SupervisorHeartbeatParamsType): Promise<SupervisorHeartbeatResponse>;
	systemHealth(params?: SystemHealthParamsType): Promise<SystemHealthResponse>;
}

export function createSupervisorMethods(call: CallFn): SupervisorMethods {
	return {
		register: (params) => call<SupervisorRegisterResponse>("supervisor/register", params),
		heartbeat: (params) => call<SupervisorHeartbeatResponse>("supervisor/heartbeat", params),
		systemHealth: (params) => call<SystemHealthResponse>("system/health", params),
	};
}
