/**
 * CLI JSON Output Schemas
 *
 * Zod schemas for JSON output shapes emitted by CLI commands.
 * These are the canonical contracts for machine-readable CLI output.
 * CLI commands use .parse() before JSON.stringify to enforce the shape.
 *
 * @module @vreko/contracts/local-service/schemas/cli-output
 */
import { z } from "zod";
const IssueSchema = z.object({
    id: z.string(),
    severity: z.enum(["warning", "error"]),
    description: z.string(),
    fix: z.string().optional(),
});
/**
 * StartStatusOutput  -  canonical shape for `vr start --json` output.
 * Both success and error paths must produce an object matching this schema
 * so machine consumers (scripts, CI, agent integrations) get a stable envelope.
 */
export const StartStatusOutput = z.discriminatedUnion("ok", [
    z.object({
        ok: z.literal(true),
        serviceRunning: z.boolean(),
        bootProfile: z.string(),
        tui: z.boolean(),
    }),
    z.object({
        ok: z.literal(false),
        error: z.string(),
    }),
]);
export const WorkspaceStatusOutput = z.object({
    initialized: z.boolean(),
    loggedIn: z.boolean(),
    user: z
        .object({
        email: z.string(),
        tier: z.enum(["free", "pro"]),
    })
        .optional(),
    workspace: z
        .object({
        id: z.string().optional(),
        tier: z.string().optional(),
        syncEnabled: z.boolean().optional(),
    })
        .optional(),
    vitals: z
        .object({
        framework: z.string().optional(),
        packageManager: z.string().optional(),
        typescript: z.boolean().optional(),
        typescriptStrict: z.boolean().optional(),
    })
        .optional(),
    session: z
        .object({
        id: z.string(),
        task: z.string().optional(),
        startedAt: z.string(),
        snapshotCount: z.number(),
    })
        .optional(),
    protection: z.object({
        count: z.number(),
        patterns: z.array(z.string()),
    }),
    violations: z.object({
        total: z.number(),
        recent: z.number(),
    }),
    snapshots: z.object({
        count: z.number(),
        totalSize: z.string(),
    }),
    intelligence: z
        .object({
        overallRisk: z.string(),
        confidence: z.number(),
        topDriver: z.string(),
        snapshotFrequency: z.string(),
    })
        .optional(),
    topologyWarning: z
        .object({
        fileCap: z.number(),
        reachedAt: z.string(),
        workspacePath: z.string(),
    })
        .optional(),
    issues: z.array(IssueSchema),
});
