/**
 * AI Config Intelligence Schemas
 *
 * Phase 6-A: AI Config Detection + Parsing
 *
 * @module @vreko/contracts/local-service/schemas/ai-config
 */
import { z } from "zod";
// =============================================================================
// AI Tool Types
// =============================================================================
/**
 * Supported AI coding tools
 */
export const AITool = z.enum([
    "cursor",
    "claude-code",
    "copilot",
    "windsurf",
    "cline",
    "universal", // AGENTS.md
]);
// =============================================================================
// File Access Rules
// =============================================================================
/**
 * File access permission rule extracted from AI config
 */
export const FileAccessRule = z.object({
    pattern: z.string(), // glob pattern
    permission: z.enum(["allow", "deny", "caution"]),
    source: z.string(), // Which instruction line this came from
});
// =============================================================================
// Parsed AI Config (Enhanced)
// =============================================================================
/**
 * Parsed AI configuration file with extracted intelligence
 */
export const ParsedAIConfig = z.object({
    // Identity
    tool: AITool,
    filePath: z.string(),
    fileName: z.string(),
    lastModifiedAt: z.number(),
    rawContent: z.string(), // Stored verbatim for change detection
    // Extracted intelligence
    protectedFiles: z.array(z.string()), // File patterns the tool was told to avoid
    focusedDomains: z.array(z.string()), // Areas tool was told to prioritize
    explicitInstructions: z.array(z.string()), // Extracted rule statements
    toolPermissions: z.array(z.string()), // Capabilities granted to agent
    workflowConstraints: z.array(z.string()), // Sequences or gates in the config
    fileAccessRules: z.array(FileAccessRule),
    behaviorRules: z.array(z.string()),
    // Computed
    vrekoInstructionsPresent: z.boolean(), // Does this file include Vreko guidance?
    vrekoSectionHash: z.string().nullable(), // Hash of Vreko-managed section
});
// =============================================================================
// AI Config Conflicts (Enhanced)
// =============================================================================
/**
 * AI configuration conflict between tools
 */
export const AIConfigConflict = z.object({
    id: z.string(),
    conflictType: z.enum(["file-access", "workflow", "behavior", "scope-overlap", "coverage-gap"]),
    tools: z.array(AITool),
    files: z.array(z.string()), // Files affected by the conflict
    description: z.string(),
    severity: z.enum(["info", "warn", "error"]),
    recommendation: z.string(),
    detectedAt: z.number(),
});
// =============================================================================
// Detection Targets
// =============================================================================
/**
 * AI config detection target definition
 */
export const AIConfigTarget = z.object({
    fileName: z.string().optional(),
    pattern: z.string().optional(),
    tool: AITool,
    priority: z.number().default(0),
});
/**
 * AI config file detection result (not to be confused with AIDetectionResult in entities.ts)
 */
export const AIConfigDetectionResult = z.object({
    filePath: z.string(),
    tool: AITool,
    exists: z.boolean(),
    lastModified: z.number().nullable(),
});
