import { z } from "zod";
export const DaemonConfig = z.object({
    daemon: z
        .object({
        memoryLimitMb: z.number().positive().default(512),
        idleTimeoutMinutes: z.number().positive().default(15),
        maxWorkspaces: z.number().positive().default(50),
        maxClients: z.number().positive().int().default(10),
        drainWindowMs: z.number().positive().default(15000),
        logLevel: z.enum(["debug", "info", "warn", "error"]).default("info"),
        crashLoopThreshold: z.number().positive().int().default(3),
        updateBehavior: z.enum(["auto", "prompt", "never"]).default("auto"),
    })
        .default({}),
    supervisor: z
        .object({
        mode: z.enum(["auto", "extension", "os"]).default("auto"),
    })
        .default({}),
});
