/**
 * Context method wrappers
 *
 * @module @vreko/local-service-client/methods/context
 */

import type {
	ContextCheckPatternsParamsType,
	ContextGetParamsType,
	ContextValidateParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface ContextGetResponse {
	patterns: Array<{ name: string; description: string }>;
	constraints: Array<{ domain: string; name: string; value: string | number; description: string }>;
	learnings: Array<{ type: string; trigger: string; action: string; relevanceScore: number }>;
	files: string[];
}

export interface ContextValidateResponse {
	valid: boolean;
	contextPath: string;
	workspace: string;
}

export interface ContextCheckPatternsResponse {
	passed: boolean;
	totalIssues: number;
	focusPoints: unknown[];
}

export interface ContextMethods {
	get(params: ContextGetParamsType): Promise<ContextGetResponse>;
	validate(params: ContextValidateParamsType): Promise<ContextValidateResponse>;
	checkPatterns(params: ContextCheckPatternsParamsType): Promise<ContextCheckPatternsResponse>;
}

export function createContextMethods(call: CallFn): ContextMethods {
	return {
		get: (params) => call<ContextGetResponse>("context/get", params),
		validate: (params) => call<ContextValidateResponse>("context/validate", params),
		checkPatterns: (params) => call<ContextCheckPatternsResponse>("context/check-patterns", params),
	};
}
