/**
 * Snapshot management method wrappers
 *
 * @module @vreko/local-service-client/methods/snapshot
 */

import type {
	Snapshot,
	SnapshotCreateParamsType,
	SnapshotDeleteParamsType,
	SnapshotDiffParamsType,
	SnapshotGetParamsType,
	SnapshotListParamsType,
	SnapshotRestoreParamsType,
} from "../types.js";
import type { CallFn } from "./health.js";

/**
 * Snapshot list response
 */
export interface SnapshotListResponse {
	/** List of snapshots */
	snapshots: Snapshot[];
	/** Pagination cursor for next page (null if no more) */
	nextCursor: string | null;
	/** Total count matching filters (if available) */
	totalCount?: number;
}

/**
 * Snapshot restore response
 */
export interface SnapshotRestoreResponse {
	/** Restored snapshot */
	snapshot: Snapshot;
	/** Path where snapshot was restored */
	restoredPath: string;
	/** Backup snapshot created before restore (if createBackup=true) */
	backupSnapshot?: Snapshot;
	/** Preview of changes (if dryRun=true) */
	preview?: {
		/** Number of lines changed */
		linesChanged: number;
		/** Unified diff preview */
		diff: string;
	};
}

/**
 * Snapshot diff response
 */
export interface SnapshotDiffResponse {
	/** Base snapshot ID */
	baseSnapshotId: string;
	/** Compare snapshot ID (or "current" if comparing to current file) */
	compareSnapshotId: string | "current";
	/** Unified or split diff output */
	diff: string;
	/** Diff statistics */
	stats: {
		/** Lines added */
		additions: number;
		/** Lines removed */
		deletions: number;
		/** Files changed */
		filesChanged: number;
	};
}

/**
 * Snapshot delete response
 */
export interface SnapshotDeleteResponse {
	/** Number of snapshots deleted */
	deletedCount: number;
	/** IDs of deleted snapshots */
	deletedIds: string[];
	/** Preview information (if dryRun=true) */
	preview?: {
		/** Snapshots that would be deleted */
		snapshotsToDelete: Snapshot[];
		/** Total size in bytes that would be freed */
		bytesFreed: number;
	};
}

/**
 * Snapshot methods namespace
 */
export interface SnapshotMethods {
	/**
	 * Create a new snapshot
	 */
	create(params: SnapshotCreateParamsType): Promise<Snapshot>;

	/**
	 * Get a specific snapshot by ID
	 */
	get(params: SnapshotGetParamsType): Promise<Snapshot>;

	/**
	 * List snapshots with optional filters
	 */
	list(params?: SnapshotListParamsType): Promise<SnapshotListResponse>;

	/**
	 * Restore a snapshot to disk
	 */
	restore(params: SnapshotRestoreParamsType): Promise<SnapshotRestoreResponse>;

	/**
	 * Generate diff between snapshots
	 */
	diff(params: SnapshotDiffParamsType): Promise<SnapshotDiffResponse>;

	/**
	 * Delete snapshots
	 */
	delete(params: SnapshotDeleteParamsType): Promise<SnapshotDeleteResponse>;
}

/**
 * Create snapshot methods namespace
 */
export function createSnapshotMethods(call: CallFn): SnapshotMethods {
	return {
		create: (params) => call<Snapshot>("snapshot/create", params),
		get: (params) => call<Snapshot>("snapshot/get", params),
		list: (params) => call<SnapshotListResponse>("snapshot/list", params),
		restore: (params) => call<SnapshotRestoreResponse>("snapshot/restore", params),
		diff: (params) => call<SnapshotDiffResponse>("snapshot/diff", params),
		delete: (params) => call<SnapshotDeleteResponse>("snapshot/delete", params),
	};
}
