/**
 * Sync method wrappers
 *
 * @module @vreko/local-service-client/methods/sync
 */

import type {
	SyncForceParamsType,
	SyncQueueParamsType,
	SyncStartParamsType,
	SyncStatusParamsDaemonType,
	SyncStopParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface SyncStatusResponse {
	running: boolean;
	lastSync: string | null;
	pendingItems: number;
	status: string;
}

export interface SyncForceResponse {
	triggered: boolean;
	error?: string;
}

export interface SyncStopResponse {
	stopped: boolean;
}

export interface SyncStartResponse {
	started: boolean;
	error?: string;
}

export interface SyncQueueResponse {
	items: unknown[];
	total: number;
}

export interface SyncMethods {
	status(params: SyncStatusParamsDaemonType): Promise<SyncStatusResponse>;
	force(params: SyncForceParamsType): Promise<SyncForceResponse>;
	stop(params: SyncStopParamsType): Promise<SyncStopResponse>;
	start(params: SyncStartParamsType): Promise<SyncStartResponse>;
	queue(params: SyncQueueParamsType): Promise<SyncQueueResponse>;
}

export function createSyncMethods(call: CallFn): SyncMethods {
	return {
		status: (params) => call<SyncStatusResponse>("sync/status-daemon", params),
		force: (params) => call<SyncForceResponse>("sync/force", params),
		stop: (params) => call<SyncStopResponse>("sync/stop", params),
		start: (params) => call<SyncStartResponse>("sync/start", params),
		queue: (params) => call<SyncQueueResponse>("sync/queue", params),
	};
}
