/**
 * AI detection method wrappers
 *
 * @module @vreko/local-service-client/methods/detection
 */

import type { DetectionCheckParamsType, DetectionSignal } from "../types.js";
import type { CallFn } from "./health.js";

/**
 * Detection check response
 */
export interface DetectionCheckResponse {
	/** Whether AI tool activity was detected */
	detected: boolean;
	/** Confidence score (0-1, higher = more confident) */
	confidence: number;
	/** Detection signals found */
	signals: DetectionSignal[];
	/** Recommended protection level based on detection */
	recommendedLevel?: "watch" | "warn" | "block";
}

/**
 * Detection methods namespace
 */
export interface DetectionMethods {
	/**
	 * Check for AI tool activity in file changes
	 */
	check(params: DetectionCheckParamsType): Promise<DetectionCheckResponse>;
}

/**
 * Create detection methods namespace
 */
export function createDetectionMethods(call: CallFn): DetectionMethods {
	return {
		check: (params) => call<DetectionCheckResponse>("detection/check", params),
	};
}
