/**
 * Violation method wrappers
 *
 * @module @vreko/local-service-client/methods/violation
 */

import type { ViolationListParamsType, ViolationReportParamsType } from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface ViolationReportResponse {
	reported: boolean;
	type: string;
	file: string;
	status: unknown;
}

export interface ViolationListResponse {
	violations: unknown[];
	total: number;
}

export interface ViolationMethods {
	report(params: ViolationReportParamsType): Promise<ViolationReportResponse>;
	list(params: ViolationListParamsType): Promise<ViolationListResponse>;
}

export function createViolationMethods(call: CallFn): ViolationMethods {
	return {
		report: (params) => call<ViolationReportResponse>("violation/report", params),
		list: (params) => call<ViolationListResponse>("violation/list", params),
	};
}
