/**
 * Risk assessment result - returned by risk/assess
 *
 * Composite of all 6 intelligence pillars.
 */
export const RiskAssessResult = z.object({
    /** Composite risk score */
    score: z.number(),
    /** Action recommendation */
    action: z.enum(["PROCEED", "PROCEED_WITH_SNAPSHOT", "WARN", "BLOCK"]),
    /** Risk level classification */
    level: z.enum(["L", "M", "H"]),
    /** Contributing factors from all pillars */
    factors: z.array(z.object({
        source: z.string(),
        score: z.number(),
        description: z.string(),
    })),
    /** Git risk pillar data */
    gitRisk: z
        .object({
        multiplier: z.number(),
        uncommittedChanges: z.boolean().optional(),
        detachedHead: z.boolean().optional(),
        onMainBranch: z.boolean().optional(),
    })
        .optional(),
    /** Fatigue pillar data */
    fatigue: z
        .object({
        level: z.enum(["rested", "normal", "elevated", "fatigued"]),
        riskBoost: z.number(),
    })
        .optional(),
    /** Rollback warning from pillar 2 */
    rollbackWarning: z
        .object({
        confidence: z.number(),
        message: z.string(),
        riskBoost: z.number(),
    })
        .optional(),
    /** Poisoning detection from pillar 5 */
    poisoning: z
        .object({
        detected: z.boolean(),
        files: z.array(z.string()).optional(),
        riskBoost: z.number().optional(),
    })
        .optional(),
    /** Per-file risk breakdown */
    fileRisks: z
        .record(z.string(), z.object({
        fragility: z.number(),
        rollbackCount: z.number().optional(),
        reason: z.string().optional(),
    }))
        .optional(),
    /** Co-change alerts */
    coChanges: z
        .array(z.object({
        source: z.string(),
        target: z.string(),
        confidence: z.number(),
    }))
        .optional(),
});
// =============================================================================
// Pulse / LLM Hint Schemas (ext_ambient/AMBIENT-01)
// =============================================================================
/**
 * LLM hint string  -  deterministic advisory prose composed by the MCP pulse tool.
 *
 * Consumed by:
 * - `vreko_pulse` MCP response (top-level `llmHint` field on ToolResult)
 * - `vreko pulse` CLI command (AMBIENT-02)
 * - Claude Code PreToolUse hook (AMBIENT-06, `jq -r '.llmHint // empty'`)
 *
 * Constraints:
 * - Always starts with "You are in <workspace>" or a known edge-case sentinel
 *   ("No active session...", "Session open, no files tracked yet...", "Pulse unavailable...").
 * - Never exceeds 400 word-tokens (tiktoken proxy via space-split).
 * - Composition is deterministic  -  no LLM generation. See
 *   `.vreko-swarm/specs/ext_ambient/03-vreko-pulse-llm-hint-spec.md`.
 */
export const LlmHintSchema = z
    .string()
    .describe("LLM hint for vreko_pulse  -  deterministic advisory prose, ≤400 word-tokens");
