/**
 * IPC connection implementation using Unix sockets / named pipes
 *
 * Memory Leak Fixes (SB-190):
 * - setupSocketHandlers() now removes old listeners before adding new ones
 * - connect() destroys socket on error to prevent orphaned handles
 * - connect() uses settled flag to prevent timeout/success race
 * - send() captures socket reference to prevent TOCTOU
 * - close() removes all listeners and destroys socket
 * - Buffer is reset on error to prevent corruption
 *
 * @module @vreko/local-service-client/connection/ipc
 */

import { existsSync } from "node:fs";
import * as net from "node:net";
import * as os from "node:os";
import * as path from "node:path";
import type { JsonRpcErrorResponse, JsonRpcNotification, JsonRpcRequest, JsonRpcResponse } from "../types.js";
import { ConnectionTimeoutError } from "../types.js";

export const SOCKET_FILENAME = "service.sock";

/**
 * Get platform-specific socket path
 */
export function getDefaultSocketPath(): string {
	const platform = os.platform();

	if (platform === "win32") {
		// Windows named pipe
		return "\\\\.\\pipe\\vreko-service";
	}

	// Unix socket (macOS/Linux)  -  check .vreko first, fall back to .vreko for 90-day compat
	const homeDir = os.homedir();
	const vrekoPath = path.join(homeDir, ".vreko", "service.sock");
	if (existsSync(vrekoPath)) {
		return vrekoPath;
	}
	return path.join(homeDir, ".vreko", "service.sock");
}

/**
 * IPC connection options
 */
export interface IpcConnectionOptions {
	/** Socket path (Unix) or pipe name (Windows) */
	socketPath?: string;
	/** Connection timeout in ms */
	timeout?: number;
}

/**
 * IPC connection events
 */
export interface IpcConnectionEvents {
	/** Emitted when message is received */
	message: (data: JsonRpcResponse | JsonRpcErrorResponse | JsonRpcNotification) => void;
	/** Emitted when connection is closed */
	close: (error?: Error) => void;
	/** Emitted on errors */
	error: (error: Error) => void;
}

/**
 * IPC connection using Unix sockets or named pipes
 */
export class IpcConnection {
	private socket: net.Socket | null = null;
	private buffer = "";
	private listeners: Partial<IpcConnectionEvents> = {};
	private readonly socketPath: string;
	private readonly timeout: number;

	constructor(options: IpcConnectionOptions = {}) {
		this.socketPath = options.socketPath ?? getDefaultSocketPath();
		this.timeout = options.timeout ?? 5000;
	}

	/**
	 * Connect to the IPC socket
	 *
	 * Fixed race conditions:
	 * - Uses settled flag to prevent timeout firing after successful connect
	 * - Destroys socket on error to prevent orphaned handles
	 * - Cleanup function ensures timeout is always cleared
	 */
	async connect(): Promise<void> {
		return new Promise((resolve, reject) => {
			const socket = net.createConnection({ path: this.socketPath });
			let timeoutId: NodeJS.Timeout | null = null;
			let settled = false;

			const cleanup = () => {
				if (timeoutId) {
					clearTimeout(timeoutId);
					timeoutId = null;
				}
			};

			// Set up timeout
			if (this.timeout > 0) {
				timeoutId = setTimeout(() => {
					if (settled) {
						return; // Already connected or errored
					}
					settled = true;
					cleanup();
					socket.destroy();
					reject(new ConnectionTimeoutError(`Connection timeout after ${this.timeout}ms`));
				}, this.timeout);
				timeoutId.unref();
			}

			socket.once("connect", () => {
				if (settled) {
					return; // Timeout already fired
				}
				settled = true;
				cleanup();
				this.socket = socket;
				this.setupSocketHandlers();
				resolve();
			});

			socket.once("error", (error) => {
				if (settled) {
					return; // Already handled
				}
				settled = true;
				cleanup();
				socket.destroy(); // Ensure socket is destroyed on error
				reject(error);
			});
		});
	}

	/**
	 * Set up socket event handlers
	 *
	 * IMPORTANT: Removes old listeners before adding new ones to prevent
	 * memory leak on reconnect. Without this, each reconnect would add
	 * duplicate handlers that never get garbage collected.
	 */
	private setupSocketHandlers(): void {
		if (!this.socket) {
			return;
		}

		// Remove old listeners before adding new ones (prevents leak on reconnect)
		this.socket.removeAllListeners("data");
		this.socket.removeAllListeners("close");
		this.socket.removeAllListeners("error");

		this.socket.on("data", (chunk) => {
			this.buffer += chunk.toString("utf8");
			this.processBuffer();
		});

		this.socket.on("close", (hadError) => {
			const error = hadError ? new Error("Socket closed with error") : undefined;
			this.emit("close", error);
			this.socket = null;
			this.buffer = ""; // Reset buffer on close
		});

		this.socket.on("error", (error) => {
			this.emit("error", error);
			// Reset buffer on error to prevent corruption from partial messages
			this.buffer = "";
		});
	}

	/**
	 * Process incoming data buffer (newline-delimited JSON)
	 */
	private processBuffer(): void {
		let newlineIndex: number;
		while ((newlineIndex = this.buffer.indexOf("\n")) !== -1) {
			const line = this.buffer.slice(0, newlineIndex);
			this.buffer = this.buffer.slice(newlineIndex + 1);

			if (line.trim().length === 0) {
				continue;
			}

			try {
				const message = JSON.parse(line);
				this.emit("message", message);
			} catch (error) {
				this.emit("error", new Error(`Failed to parse JSON-RPC message: ${(error as Error).message}`));
			}
		}
	}

	/**
	 * Send a JSON-RPC request
	 *
	 * TOCTOU Fix: Captures socket reference at start to prevent race condition
	 * where socket becomes null between the check and the write.
	 */
	async send(request: JsonRpcRequest): Promise<void> {
		// Capture reference to prevent TOCTOU race
		const socket = this.socket;
		if (!socket || socket.destroyed) {
			throw new Error("Socket not connected");
		}

		return new Promise((resolve, reject) => {
			const data = `${JSON.stringify(request)}\n`;
			socket.write(data, "utf8", (error: Error | null | undefined) => {
				if (error) {
					reject(error);
				} else {
					resolve();
				}
			});
		});
	}

	/**
	 * Close the connection
	 *
	 * Proper cleanup:
	 * - Removes all listeners to prevent memory leaks
	 * - Calls end() for graceful close
	 * - Calls destroy() to ensure immediate cleanup
	 * - Resets buffer to prevent stale data on reconnect
	 */
	close(): void {
		if (this.socket) {
			// Remove all listeners to prevent memory leaks
			this.socket.removeAllListeners();
			// End gracefully then destroy
			this.socket.end();
			this.socket.destroy();
			this.socket = null;
		}
		this.buffer = "";
	}

	/**
	 * Check if connected
	 */
	isConnected(): boolean {
		return this.socket !== null && !this.socket.destroyed;
	}

	/**
	 * Register event listener
	 */
	on<K extends keyof IpcConnectionEvents>(event: K, handler: IpcConnectionEvents[K]): void {
		this.listeners[event] = handler;
	}

	/**
	 * Remove event listener
	 */
	off<K extends keyof IpcConnectionEvents>(event: K): void {
		delete this.listeners[event];
	}

	/**
	 * Emit event
	 */
	private emit<K extends keyof IpcConnectionEvents>(event: K, ...args: Parameters<IpcConnectionEvents[K]>): void {
		const handler = this.listeners[event];
		if (handler) {
			// @ts-expect-error - Type inference limitation with variadic args
			handler(...args);
		}
	}
}
