/**
 * Auto-reconnection logic with exponential backoff using p-retry
 *
 * This is a lightweight wrapper around p-retry that maintains backward compatibility
 * with the original ReconnectManager API while consolidating retry logic.
 *
 * @module @vreko/local-service-client/connection/reconnect
 */

import pRetry, { type Options as PRetryOptions } from "p-retry";

/**
 * Reconnection strategy options
 */
export interface ReconnectOptions {
	/** Maximum number of reconnection attempts */
	maxAttempts: number;
	/** Initial delay in ms */
	initialDelay: number;
	/** Maximum delay in ms (for exponential backoff cap) */
	maxDelay: number;
	/** Backoff multiplier */
	backoffMultiplier: number;
}

/**
 * Reconnection manager with exponential backoff (p-retry wrapper)
 *
 * This class now delegates retry logic to p-retry for consistency across the codebase.
 */
export class ReconnectManager {
	private isReconnecting = false;
	private abortController: AbortController | null = null;
	private readonly options: ReconnectOptions;

	constructor(options: Partial<ReconnectOptions> = {}) {
		this.options = {
			maxAttempts: options.maxAttempts ?? 5,
			initialDelay: options.initialDelay ?? 1000,
			maxDelay: options.maxDelay ?? 30000,
			backoffMultiplier: options.backoffMultiplier ?? 2,
		};
	}

	/**
	 * Start reconnection process
	 */
	async start(
		connectFn: () => Promise<void>,
		onAttempt?: (attempt: number, maxAttempts: number) => void,
		onFailed?: () => void,
	): Promise<void> {
		if (this.isReconnecting) {
			return;
		}

		this.isReconnecting = true;
		this.abortController = new AbortController();

		const pRetryOptions: PRetryOptions = {
			retries: this.options.maxAttempts,
			factor: this.options.backoffMultiplier,
			minTimeout: this.options.initialDelay,
			maxTimeout: this.options.maxDelay,
			randomize: false, // Maintain original deterministic behavior
			signal: this.abortController.signal,
			onFailedAttempt: (error) => {
				if (onAttempt) {
					onAttempt(error.attemptNumber, this.options.maxAttempts);
				}
			},
		};

		try {
			await pRetry(connectFn, pRetryOptions);
			this.reset();
		} catch (error) {
			this.reset();
			if (onFailed) {
				onFailed();
			}
			throw error;
		}
	}

	/**
	 * Stop reconnection process
	 */
	stop(): void {
		if (this.abortController) {
			this.abortController.abort();
			this.abortController = null;
		}
		this.reset();
	}

	/**
	 * Reset reconnection state
	 */
	private reset(): void {
		this.isReconnecting = false;
	}

	/**
	 * Check if currently reconnecting
	 */
	isActive(): boolean {
		return this.isReconnecting;
	}

	/**
	 * Get current attempt number (not tracked in p-retry wrapper)
	 * @deprecated p-retry handles attempt tracking internally
	 */
	getCurrentAttempt(): number {
		// This method is deprecated but kept for backward compatibility
		return this.isReconnecting ? 1 : 0;
	}
}
