/**
 * Daemon lifecycle method wrappers
 *
 * @module @vreko/local-service-client/methods/daemon
 */

import type { CallFn } from "./health.js";

export interface DaemonPingResponse {
	pong: true;
	uptime: number;
	version: string;
}

export interface DaemonStatusResponse {
	pid: number;
	version: string;
	uptime: number;
	startedAt: string;
	workspaces: number;
	connections: number;
	memoryUsage: { heapUsed: number; heapTotal: number; rss: number };
	lastActivity: number;
	/** Idle timeout in milliseconds */
	idleTimeout: number;
	/** Authentication status from CLI credentials */
	auth?: {
		authenticated: boolean;
		user?: string;
		tier?: string;
	};
}

export interface DaemonShutdownResponse {
	shutting_down: true;
}

export interface DaemonReloadResponse {
	reloaded: true;
}

export interface DaemonMethods {
	ping(): Promise<DaemonPingResponse>;
	status(): Promise<DaemonStatusResponse>;
	shutdown(): Promise<DaemonShutdownResponse>;
	reload(): Promise<DaemonReloadResponse>;
}

export function createDaemonMethods(call: CallFn): DaemonMethods {
	return {
		ping: () => call<DaemonPingResponse>("daemon/ping"),
		status: () => call<DaemonStatusResponse>("daemon/status"),
		shutdown: () => call<DaemonShutdownResponse>("daemon/shutdown"),
		reload: () => call<DaemonReloadResponse>("daemon/reload"),
	};
}
