/**
 * Artifact File Schema (ext_ambient/AMBIENT-03)
 *
 * Generic envelope for any markdown/text artifact the daemon writes under
 * `.vreko/docs/` (and eventually elsewhere). The `owner` discriminator
 * lets consumers tell daemon-generated files apart from user-authored
 * additions so no write path overwrites hand-edited content.
 *
 * Consumed by:
 * - `DocsEmitter` projector (writes markdown under .vreko/docs/)
 * - `PointerService` (AMBIENT-04  -  materializes pointer references)
 *
 * @module @vreko/contracts/local-service/artifact
 */
import { z } from "zod";
export const ArtifactFileSchema = z.object({
    /** Absolute path to the file on disk. */
    path: z.string(),
    /** Serialized artifact content (markdown/text). */
    content: z.string(),
    /** SHA-256 of `content`  -  used for skip-if-unchanged checks. */
    hash: z.string(),
    /** Milliseconds since epoch when the artifact was generated. */
    generatedAt: z.number(),
    /**
     * Who owns this file. `vreko` = daemon may overwrite; `user` = hands off.
     * DocsEmitter only writes files it owns; any path a user has taken over
     * (tracked via a separate manifest in future phases) must be skipped.
     */
    owner: z.enum(["vreko", "user"]),
});
