/**
 * Vreko Local Service Client
 *
 * TypeScript client for connecting to vrekod via IPC (Unix sockets / named pipes).
 * Provides type-safe method wrappers for all Local Service Protocol methods.
 *
 * @module @vreko/local-service-client
 *
 * @example
 * ```typescript
 * import { VrekoLocalClient } from '@vreko/local-service-client';
 *
 * const client = new VrekoLocalClient();
 * await client.connect();
 *
 * // Initialize connection
 * await client.initialize({
 *   protocolVersion: '1.0.0',
 *   clientInfo: { name: 'my-app', version: '1.0.0' }
 * });
 *
 * // Create a snapshot
 * const snapshot = await client.snapshot.create({
 *   filePath: '/path/to/file.ts',
 *   content: 'const x = 1;',
 *   trigger: 'save'
 * });
 *
 * await client.close();
 * ```
 */

import { getDefaultSocketPath, IpcConnection } from "./connection/ipc.js";
import { ReconnectManager } from "./connection/reconnect.js";
import { createContextMethods } from "./methods/context.js";
import { createDaemonMethods } from "./methods/daemon.js";
import { createDetectionMethods } from "./methods/detection.js";
import { createHealthMethods } from "./methods/health.js";
import type {
	ContextMethods,
	DaemonMethods,
	DetectionMethods,
	HealthMethods,
	IntelligenceMethods,
	LearningMethods,
	MCPMethods,
	MomentumMethods,
	ProtectionMethods,
	SessionMethods,
	SnapshotMethods,
	SupervisorMethods,
	SyncMethods,
	ValidationMethods,
	ViolationMethods,
	WatchMethods,
	WorkspaceMethods,
} from "./methods/index.js";
import { createIntelligenceMethods } from "./methods/intelligence.js";
import { createLearningMethods } from "./methods/learning.js";
import { createMCPMethods } from "./methods/mcp.js";
import { createMomentumMethods } from "./methods/momentum.js";
import { createProtectionMethods } from "./methods/protection.js";
import { createSessionMethods } from "./methods/session.js";
import { createSnapshotMethods } from "./methods/snapshot.js";
import { createSupervisorMethods } from "./methods/supervisor.js";
import { createSyncMethods } from "./methods/sync.js";
import { createValidationMethods } from "./methods/validation.js";
import { createViolationMethods } from "./methods/violation.js";
import { createWatchMethods } from "./methods/watch.js";
import { createWorkspaceMethods } from "./methods/workspace.js";
import type {
	ClientEvents,
	ClientOptions,
	ConnectionState,
	JsonRpcErrorResponse,
	JsonRpcNotification,
	JsonRpcRequest,
	JsonRpcResponse,
	LocalServiceMethod,
} from "./types.js";
import { JsonRpcClientError, RequestTimeoutError } from "./types.js";

/**
 * Pending request tracker
 */
interface PendingRequest {
	resolve: (value: unknown) => void;
	reject: (error: Error) => void;
	timeout: NodeJS.Timeout;
}

/**
 * Vreko Local Service Client
 *
 * Main client class for interacting with vrekod daemon.
 */
export class VrekoLocalClient {
	private connection: IpcConnection;
	private reconnectManager: ReconnectManager;
	private state: ConnectionState = "disconnected";
	private nextId = 1;
	private pending = new Map<string | number, PendingRequest>();
	private eventHandlers: Partial<ClientEvents> = {};
	private options: Required<ClientOptions>;
	/** Stored params from the last initialize() call  -  replayed after auto-reconnect */
	private initializeParams: Parameters<VrekoLocalClient["initialize"]>[0] | null = null;

	// Method namespaces - original
	public readonly health: HealthMethods;
	public readonly session: SessionMethods;
	public readonly snapshot: SnapshotMethods;
	public readonly protection: ProtectionMethods;
	public readonly detection: DetectionMethods;
	// Method namespaces - new domains
	public readonly learning: LearningMethods;
	public readonly context: ContextMethods;
	public readonly validation: ValidationMethods;
	public readonly violation: ViolationMethods;
	public readonly sync: SyncMethods;
	public readonly intelligence: IntelligenceMethods;
	public readonly momentum: MomentumMethods;
	public readonly watch: WatchMethods;
	public readonly mcp: MCPMethods;
	public readonly supervisor: SupervisorMethods;
	public readonly daemon: DaemonMethods;
	public readonly workspace: WorkspaceMethods;

	constructor(options: ClientOptions = {}) {
		this.options = {
			socketPath: options.socketPath ?? getDefaultSocketPath(),
			timeout: options.timeout ?? 30000,
			autoReconnect: options.autoReconnect ?? true,
			maxReconnectAttempts: options.maxReconnectAttempts ?? 5,
			reconnectDelay: options.reconnectDelay ?? 1000,
			maxReconnectDelay: options.maxReconnectDelay ?? 30000,
		};

		this.connection = new IpcConnection({
			socketPath: this.options.socketPath,
			timeout: 5000, // Connection timeout
		});

		this.reconnectManager = new ReconnectManager({
			maxAttempts: this.options.maxReconnectAttempts,
			initialDelay: this.options.reconnectDelay,
			maxDelay: this.options.maxReconnectDelay,
		});

		// Bind method namespaces - original
		const callFn = this.call.bind(this);
		this.health = createHealthMethods(callFn);
		this.session = createSessionMethods(callFn);
		this.snapshot = createSnapshotMethods(callFn);
		this.protection = createProtectionMethods(callFn);
		this.detection = createDetectionMethods(callFn);
		// Bind method namespaces - new domains
		this.learning = createLearningMethods(callFn);
		this.context = createContextMethods(callFn);
		this.validation = createValidationMethods(callFn);
		this.violation = createViolationMethods(callFn);
		this.sync = createSyncMethods(callFn);
		this.intelligence = createIntelligenceMethods(callFn);
		this.momentum = createMomentumMethods(callFn);
		this.watch = createWatchMethods(callFn);
		this.mcp = createMCPMethods(callFn);
		this.supervisor = createSupervisorMethods(callFn);
		this.daemon = createDaemonMethods(callFn);
		this.workspace = createWorkspaceMethods(callFn);

		this.setupConnectionHandlers();
	}

	/**
	 * Set up IPC connection event handlers
	 */
	private setupConnectionHandlers(): void {
		this.connection.on("message", (message) => {
			// Check if it's a notification (no id field)
			if ("method" in message && !("id" in message)) {
				const notification = message as JsonRpcNotification;
				this.emit("notification", notification.method, notification.params);
				return;
			}

			// Handle response
			const response = message as JsonRpcResponse | JsonRpcErrorResponse;

			// Ignore responses with null id (parse errors)
			if (response.id === null) {
				this.emit("error", new Error("Received error response with null id"));
				return;
			}

			const pending = this.pending.get(response.id);

			if (!pending) {
				// Unexpected response - emit error
				this.emit("error", new Error(`Received response for unknown request ID: ${response.id}`));
				return;
			}

			// Clear timeout
			clearTimeout(pending.timeout);
			this.pending.delete(response.id);

			// Handle error response
			if ("error" in response) {
				const error = new JsonRpcClientError(response.error.message, response.error.code, response.error.data);
				pending.reject(error);
				return;
			}

			// Handle success response
			pending.resolve(response.result);
		});

		this.connection.on("close", (error) => {
			// Don't override "closed"  -  close() sets it synchronously before socket teardown
			if (this.state !== "closed") {
				this.setState("disconnected");
			}
			this.emit("disconnected", error);

			// Clear all pending requests
			for (const [, pending] of this.pending.entries()) {
				clearTimeout(pending.timeout);
				pending.reject(new Error("Connection closed"));
			}
			this.pending.clear();

			// Attempt reconnection only if not intentionally closed
			if (this.options.autoReconnect && this.state !== "closed" && !this.reconnectManager.isActive()) {
				this.attemptReconnect();
			}
		});

		this.connection.on("error", (error) => {
			this.emit("error", error);
		});
	}

	/**
	 * Attempt to reconnect
	 */
	private async attemptReconnect(): Promise<void> {
		this.setState("reconnecting");

		try {
			await this.reconnectManager.start(
				async () => {
					await this.connection.connect();
					// Replay the initialize handshake  -  the server assigns a new clientId
					// for every socket connection, so the server-side initializedClients Set
					// won't recognise this connection until we re-initialize.
					if (this.initializeParams) {
						await this.initialize(this.initializeParams);
					}
					this.setState("connected");
					this.emit("connected");
				},
				(attempt, maxAttempts) => {
					this.emit("reconnecting", attempt, maxAttempts);
				},
				() => {
					this.emit("reconnectFailed");
				},
			);
		} catch (error) {
			this.setState("disconnected");
			this.emit("error", error as Error);
		}
	}

	/**
	 * Connect to the local service
	 */
	async connect(): Promise<void> {
		if (this.state === "connected" || this.state === "connecting") {
			return;
		}

		this.setState("connecting");

		try {
			await this.connection.connect();
			this.setState("connected");
			this.emit("connected");
		} catch (error) {
			this.setState("disconnected");
			throw error;
		}
	}

	/**
	 * Close the connection
	 */
	close(): void {
		this.reconnectManager.stop();
		this.connection.close();
		this.setState("closed");

		// Clear all pending requests
		for (const [, pending] of this.pending.entries()) {
			clearTimeout(pending.timeout);
			pending.reject(new Error("Client closed"));
		}
		this.pending.clear();
	}

	/**
	 * Make a JSON-RPC method call
	 */
	async call<TResult = unknown>(method: LocalServiceMethod, params?: unknown): Promise<TResult> {
		if (!this.connection.isConnected()) {
			throw new Error("Not connected to service");
		}

		const id = this.nextId++;
		const request: JsonRpcRequest = {
			jsonrpc: "2.0",
			id,
			method,
			params,
		};

		return new Promise<TResult>((resolve, reject) => {
			// Set up timeout  -  unref so a pending timeout doesn't keep the CLI process alive
			const timeout = setTimeout(() => {
				this.pending.delete(id);
				reject(new RequestTimeoutError(`Request timeout after ${this.options.timeout}ms`, id));
			}, this.options.timeout).unref();

			// Track pending request
			this.pending.set(id, {
				resolve: resolve as (value: unknown) => void,
				reject,
				timeout,
			});

			// Send request
			this.connection.send(request).catch((error) => {
				clearTimeout(timeout);
				this.pending.delete(id);
				reject(error);
			});
		});
	}

	/**
	 * Initialize the client connection
	 *
	 * Must be called before any other method calls.
	 * Params are stored and automatically replayed after auto-reconnect.
	 */
	async initialize(params: {
		protocolVersion: string;
		clientInfo: { name: string; version: string };
		capabilities?: {
			notifications?: boolean;
			binaryContent?: boolean;
		};
	}): Promise<{
		protocolVersion: string;
		serverInfo: { name: string; version: string };
		capabilities: {
			notifications: boolean;
			binaryContent: boolean;
		};
	}> {
		// Store params so they can be replayed after auto-reconnect
		this.initializeParams = params;
		return this.call("initialize", params);
	}

	/**
	 * Get current connection state
	 */
	getState(): ConnectionState {
		return this.state;
	}

	/**
	 * Check if connected
	 */
	isConnected(): boolean {
		return this.state === "connected";
	}

	/**
	 * Register event listener
	 */
	on<K extends keyof ClientEvents>(event: K, handler: ClientEvents[K]): void {
		this.eventHandlers[event] = handler;
	}

	/**
	 * Remove event listener
	 */
	off<K extends keyof ClientEvents>(event: K): void {
		delete this.eventHandlers[event];
	}

	/**
	 * Set connection state and emit event
	 */
	private setState(state: ConnectionState): void {
		if (this.state !== state) {
			this.state = state;
			this.emit("stateChange", state);
		}
	}

	/**
	 * Emit event to registered handlers
	 */
	private emit<K extends keyof ClientEvents>(event: K, ...args: Parameters<ClientEvents[K]>): void {
		const handler = this.eventHandlers[event];
		if (handler) {
			// @ts-expect-error - Type inference limitation with variadic args
			handler(...args);
		}
	}
}
