/**
 * Workspace method wrappers
 *
 * @module @vreko/local-service-client/methods/workspace
 */

import type { CallFn } from "./health.js";

// =============================================================================
// Types
// =============================================================================

export type AnalysisPhase = "structure" | "git" | "baseline" | "learnings" | "readiness";

export interface AnalysisProgress {
	phase: AnalysisPhase;
	progress: number;
	message?: string;
}

export interface ReadinessAssessment {
	score: number;
	level: "ready" | "partial" | "minimal";
	factors: {
		hasBaseline: boolean;
		hasLearnings: boolean;
		hasProfile: boolean;
		healthScore: number;
	};
	recommendations: string[];
}

export interface WorkspaceProfile {
	framework: {
		id: string;
		name: string;
		confidence: number;
	};
	healthScore: number;
	gaps?: Array<{
		type: string;
		severity: "critical" | "warning" | "info";
		message: string;
	}>;
}

export interface WorkspaceAnalyzeParams {
	workspace: string;
	skipBaseline?: boolean;
	skipLearnings?: boolean;
	forceSeedLearnings?: boolean;
}

export interface WorkspaceAnalyzeResponse {
	workspace: string;
	profile: WorkspaceProfile | null;
	baselineJobId: string | null;
	learningsSeeded: {
		seeded: boolean;
		count: number;
		tiers: { hot: number; warm: number; cold: number };
		alreadySeeded: boolean;
	};
	readiness: ReadinessAssessment;
	duration: number;
	analyzedAt: string;
}

export interface WorkspaceStatusParams {
	workspace: string;
}

export interface WorkspaceStatusResponse {
	workspace: string;
	hasProfile: boolean;
	baselineStatus: string;
	learningsCount: number;
}

// =============================================================================
// Methods
// =============================================================================

export interface WorkspaceMethods {
	analyze(params: WorkspaceAnalyzeParams): Promise<WorkspaceAnalyzeResponse>;
	status(params: WorkspaceStatusParams): Promise<WorkspaceStatusResponse>;
}

export function createWorkspaceMethods(call: CallFn): WorkspaceMethods {
	return {
		analyze: (params) => call<WorkspaceAnalyzeResponse>("workspace/analyze", params),
		status: (params) => call<WorkspaceStatusResponse>("workspace/status", params),
	};
}
