/**
 * Learning method wrappers
 *
 * @module @vreko/local-service-client/methods/learning
 */

import type {
	LearningAddParamsType,
	LearningEvaluateParamsType,
	LearningGCParamsType,
	LearningListParamsType,
	LearningPruneParamsType,
	LearningSearchParamsType,
	LearningUpdateSessionParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface LearningAddResponse {
	success: boolean;
	type: string;
	trigger: string;
	action: string;
}

export interface LearningSearchResponse {
	learnings: Array<{ type: string; trigger: string; action: string; relevanceScore: number }>;
	total: number;
}

export interface LearningListResponse {
	learnings: Array<{ type: string; trigger: string; action: string }>;
	total: number;
}

export interface LearningPruneResponse {
	pruned: number;
	remaining: number;
}

export interface LearningEvaluateResponse {
	applicable: Array<{ type: string; trigger: string; action: string; relevanceScore: number }>;
	mode: string;
	commandName: string;
}

export interface LearningUpdateSessionResponse {
	success: boolean;
	sessionId: string;
	updated: number;
}

export interface LearningGCResponse {
	operation: string;
	dryRun: boolean;
	archived: number;
	deleted: number;
	remaining: number;
}

export interface LearningSeedParams {
	workspace: string;
	learnings?: Array<{
		id?: string;
		type: string;
		tier?: string;
		trigger: string;
		action: string;
		solution?: string;
		source?: string;
		timestamp?: string;
		priority?: string;
		domain?: string;
	}>;
	framework?: string;
	force?: boolean;
}

export interface LearningSeedResponse {
	seeded: boolean;
	learningsAdded: number;
	tiers: { hot: number; warm: number; cold: number };
	alreadySeeded: boolean;
	framework: string | null;
}

export interface LearningConsolidateParams {
	workspace: string;
	threshold?: number;
	dryRun?: boolean;
}

export interface LearningConsolidateResponse {
	success: boolean;
	originalCount: number;
	consolidatedCount: number;
	duplicatesFound: number;
	reductionPercent: number;
	archivePath?: string;
	dryRun: boolean;
}

export interface LearningMethods {
	add(params: LearningAddParamsType): Promise<LearningAddResponse>;
	search(params: LearningSearchParamsType): Promise<LearningSearchResponse>;
	list(params: LearningListParamsType): Promise<LearningListResponse>;
	prune(params: LearningPruneParamsType): Promise<LearningPruneResponse>;
	evaluate(params: LearningEvaluateParamsType): Promise<LearningEvaluateResponse>;
	updateSession(params: LearningUpdateSessionParamsType): Promise<LearningUpdateSessionResponse>;
	gc(params: LearningGCParamsType): Promise<LearningGCResponse>;
	seed(params: LearningSeedParams): Promise<LearningSeedResponse>;
	consolidate(params: LearningConsolidateParams): Promise<LearningConsolidateResponse>;
}

export function createLearningMethods(call: CallFn): LearningMethods {
	return {
		add: (params) => call<LearningAddResponse>("learning/add", params),
		search: (params) => call<LearningSearchResponse>("learning/search", params),
		list: (params) => call<LearningListResponse>("learning/list", params),
		prune: (params) => call<LearningPruneResponse>("learning/prune", params),
		evaluate: (params) => call<LearningEvaluateResponse>("learning/evaluate", params),
		updateSession: (params) => call<LearningUpdateSessionResponse>("learning/update-session", params),
		gc: (params) => call<LearningGCResponse>("learning/gc", params),
		seed: (params) => call<LearningSeedResponse>("learning/seed", params),
		consolidate: (params) => call<LearningConsolidateResponse>("learning/consolidate", params),
	};
}
