/**
 * Type re-exports from @vreko/contracts for convenience
 *
 * @module @vreko/local-service-client/types
 */

// Import types for local use
import type { ErrorData } from "@vreko/contracts/local-service";

// Re-export all protocol types and interfaces
// Re-export all entity types (using the TypeScript type exports with "Type" suffix)
// Re-export all request parameter types
export type {
	AnalyzeGroupingParamsType,
	AnalyzeRiskParamsType,
	DetectionCheckParamsType,
	DetectionSignalType as DetectionSignal,
	ErrorData,
	HealthCheckParamsType,
	InitializeParamsType,
	JsonRpcError,
	JsonRpcErrorResponse,
	JsonRpcNotification,
	JsonRpcRequest,
	JsonRpcResponse,
	LocalServiceMethod,
	ProtectionDecisionType as ProtectionDecision,
	ProtectionEvaluateParamsType,
	ProtectionFactorType as ProtectionFactor,
	ProtectionLevelsParamsType,
	ProtectionLevelType as ProtectionLevel,
	ProtectionSetParamsType,
	ProtocolVersionType,
	RiskFactorType as RiskFactor,
	RiskLevelType as RiskLevel,
	SessionCurrentParamsType,
	SessionEndParamsType,
	SessionListParamsType,
	SessionStartParamsType,
	SessionStateType as SessionState,
	SessionType as Session,
	SnapshotCreateParamsType,
	SnapshotDeleteParamsType,
	SnapshotDiffParamsType,
	SnapshotGetParamsType,
	SnapshotListParamsType,
	SnapshotRestoreParamsType,
	SnapshotTriggerType as SnapshotTrigger,
	SnapshotType as Snapshot,
	SyncTriggerParamsType,
	TierType as Tier,
} from "@vreko/contracts/local-service";
export {
	ERROR_MESSAGES,
	PROTOCOL_VERSION,
	ProtocolErrorCode,
} from "@vreko/contracts/local-service";

/**
 * Client configuration options
 */
export interface ClientOptions {
	/**
	 * Socket path (Unix) or pipe name (Windows)
	 * Defaults to platform-specific path
	 */
	socketPath?: string;

	/**
	 * Default request timeout in milliseconds
	 * @default 30000
	 */
	timeout?: number;

	/**
	 * Enable auto-reconnect on connection loss
	 * @default true
	 */
	autoReconnect?: boolean;

	/**
	 * Maximum reconnection attempts
	 * @default 5
	 */
	maxReconnectAttempts?: number;

	/**
	 * Initial reconnect delay in milliseconds
	 * @default 1000
	 */
	reconnectDelay?: number;

	/**
	 * Maximum reconnect delay in milliseconds (for exponential backoff)
	 * @default 30000
	 */
	maxReconnectDelay?: number;
}

/**
 * Client connection state
 */
export type ConnectionState = "disconnected" | "connecting" | "connected" | "reconnecting" | "closed";

/**
 * Client events
 */
export interface ClientEvents {
	/** Emitted when connection state changes */
	stateChange: (state: ConnectionState) => void;
	/** Emitted when connection is established */
	connected: () => void;
	/** Emitted when connection is lost */
	disconnected: (error?: Error) => void;
	/** Emitted when reconnecting */
	reconnecting: (attempt: number, maxAttempts: number) => void;
	/** Emitted when max reconnect attempts reached */
	reconnectFailed: () => void;
	/** Emitted when server sends a notification */
	notification: (method: string, params: unknown) => void;
	/** Emitted on errors */
	error: (error: Error) => void;
}

/**
 * JSON-RPC error class
 */
export class JsonRpcClientError extends Error {
	public readonly code: number;
	public readonly data?: ErrorData;

	constructor(message: string, code: number, data?: ErrorData) {
		super(message);
		this.name = "JsonRpcClientError";
		this.code = code;
		this.data = data;
	}
}

/**
 * Connection timeout error
 */
export class ConnectionTimeoutError extends Error {
	constructor(message = "Connection timeout") {
		super(message);
		this.name = "ConnectionTimeoutError";
	}
}

/**
 * Request timeout error
 */
export class RequestTimeoutError extends Error {
	constructor(
		message = "Request timeout",
		public requestId?: string | number,
	) {
		super(message);
		this.name = "RequestTimeoutError";
	}
}
