/**
 * Daemon Health Contracts
 *
 * Canonical health state schema for the daemon. The daemon is the single
 * source of truth for health state  -  extensions and CLI consumers MUST
 * import these types, never redefine them locally.
 *
 * Design principles (see ADR in .vreko-swarm/anti-patterns.md):
 * - Daemon declares health; clients consume (gRPC health.proto pattern)
 * - Liveness separate from readiness (Kubernetes probe pattern)
 * - Hysteresis prevents flapping (Schmitt trigger)
 * - Push-first, poll-fallback (gRPC Watch pattern)
 *
 * @module @vreko/contracts/local-service/schemas/health
 */
import { z } from "zod";
// =============================================================================
// Health State Enum
// =============================================================================
/**
 * Canonical daemon health states.
 *
 * - healthy:   All subsystems operational
 * - degraded:  Some subsystems impaired but core functionality available
 * - unhealthy: Critical subsystems down, cannot serve requests reliably
 * - unknown:   State not yet determined (startup, reconnection)
 */
export const DaemonHealthState = z.enum(["healthy", "degraded", "unhealthy", "unknown"]);
// =============================================================================
// Subsystem Names
// =============================================================================
/**
 * Named subsystems tracked by the health authority.
 * Each reports independently; the authority aggregates into a single state.
 */
export const SubsystemName = z.enum(["ipc", "mcp", "supervisor", "fileWatcher", "sessions", "sync"]);
// =============================================================================
// Subsystem Status
// =============================================================================
/**
 * Individual subsystem health report.
 */
export const SubsystemStatus = z.object({
    /** Current health state of this subsystem */
    state: DaemonHealthState,
    /** Human-readable reason for current state (omitted when healthy) */
    reason: z.string().optional(),
    /** ISO8601 timestamp of last state transition */
    lastTransition: z.string().datetime().nullable(),
});
// =============================================================================
// Daemon Health Report
// =============================================================================
/**
 * Complete health report returned by health/check.
 *
 * The `state` field is the aggregate  -  worst-of-all subsystems with
 * hysteresis applied (degraded requires 3 consecutive failures;
 * recovery requires 5 consecutive successes).
 */
export const DaemonHealthReport = z.object({
    /** Aggregate health state (worst of all subsystems, with hysteresis) */
    state: DaemonHealthState,
    /** Daemon uptime in milliseconds */
    uptime: z.number().nonnegative(),
    /** Per-subsystem health breakdown */
    subsystems: z.record(SubsystemName, SubsystemStatus),
    /** ISO8601 timestamp of last aggregate state transition */
    lastTransition: z.string().datetime().nullable(),
    /** Human-readable reason for degraded/unhealthy state */
    degradedReason: z.string().optional(),
    /** ISO8601 timestamp of this report */
    timestamp: z.string().datetime(),
});
// =============================================================================
// Health Changed Notification
// =============================================================================
/**
 * Payload for $/health-changed push notification.
 * Sent by daemon whenever the aggregate health state transitions.
 */
export const HealthChangedNotification = z.object({
    /** Previous aggregate state */
    previousState: DaemonHealthState,
    /** New aggregate state */
    currentState: DaemonHealthState,
    /** Human-readable reason for the transition */
    reason: z.string(),
    /** Unix timestamp (ms) when the transition occurred */
    timestamp: z.number().nonnegative(),
    /** Full health report at time of transition */
    report: DaemonHealthReport,
});
// =============================================================================
// Health Check Response V2 (Phase 18  -  daemon lifecycle v2)
// =============================================================================
/**
 * Extended health check response with daemon resource state, lifecycle state,
 * and component breakdown. Introduced in Phase 18 alongside supervisor mode
 * detection and structured Sentry error taxonomy.
 */
export const HealthCheckResponseV2 = DaemonHealthReport.extend({
    // Daemon resource state
    memoryMb: z.number().nonnegative(),
    memoryLimitMb: z.number().positive(),
    ipcQueueDepth: z.number().nonnegative(),
    activeRequests: z.number().nonnegative(),
    // Lifecycle state
    lastCleanShutdown: z.boolean(),
    supervisorMode: z.enum(["launchd", "systemd", "extension", "none"]),
    // Component breakdown
    components: z.object({
        ipcServer: z.enum(["ok", "degraded"]),
        fileWatcher: z.enum(["ok", "degraded", "unavailable"]),
        syncService: z.enum(["ok", "degraded", "disabled"]),
        intelligenceService: z.enum(["ok", "degraded"]),
    }),
});
export const HealthPingResult = z.object({
    status: z.literal("ok"),
});
