/**
 * Session management method wrappers
 *
 * @module @vreko/local-service-client/methods/session
 */

import type {
	Session,
	SessionCurrentParamsType,
	SessionEndParamsType,
	SessionListParamsType,
	SessionStartParamsType,
} from "../types.js";
import type { CallFn } from "./health.js";

/**
 * Session list response
 */
export interface SessionListResponse {
	/** List of sessions */
	sessions: Session[];
	/** Pagination cursor for next page (null if no more) */
	nextCursor: string | null;
	/** Total count (if available) */
	totalCount?: number;
}

/**
 * Session vitals response (workspace health metrics)
 */
export interface SessionVitalsResponse {
	framework?: string;
	packageManager?: string;
	typescript?: { enabled: boolean; strict: boolean };
	[key: string]: unknown;
}

/**
 * Session methods namespace
 */
export interface SessionMethods {
	/**
	 * Get current active session
	 */
	current(params?: SessionCurrentParamsType): Promise<Session | null>;

	/**
	 * Start a new session
	 */
	start(params: SessionStartParamsType): Promise<Session>;

	/**
	 * End the current or specified session
	 */
	end(params?: SessionEndParamsType): Promise<Session>;

	/**
	 * List sessions with optional filters
	 */
	list(params?: SessionListParamsType): Promise<SessionListResponse>;

	/**
	 * Get real-time workspace vitals (framework, package manager, TypeScript config)
	 */
	vitals(params: { workspacePath: string }): Promise<SessionVitalsResponse>;
}

/**
 * Create session methods namespace
 */
export function createSessionMethods(call: CallFn): SessionMethods {
	return {
		current: (params) => call<Session | null>("session/current", params),
		start: (params) => call<Session>("session/start", params),
		end: (params) => call<Session>("session/end", params),
		list: (params) => call<SessionListResponse>("session/list", params),
		vitals: (params) => call<SessionVitalsResponse>("session/vitals", params),
	};
}
