/**
 * Momentum method wrappers
 *
 * @module @vreko/local-service-client/methods/momentum
 */

import type {
	MomentumRefreshParamsType,
	MomentumScoreParamsType,
	MomentumStatusParamsType,
	MomentumSyncParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface MomentumRefreshResponse {
	refreshed: boolean;
	since: string;
	full: boolean;
	scores: Record<string, unknown>;
	timestamp: number;
}

export interface MomentumScoreResponse {
	filePath: string;
	score: number;
	factors: { changeFrequency: number; complexity: number; recency: number };
	timestamp: number;
}

export interface MomentumSyncResponse {
	synced: boolean;
	quick: boolean;
	filesAnalyzed: number;
	timestamp: number;
}

export interface MomentumStatusResponse {
	active: boolean;
	lastSync: string | null;
	fileCount: number;
	averageScore: number;
}

export interface MomentumMethods {
	refresh(params: MomentumRefreshParamsType): Promise<MomentumRefreshResponse>;
	score(params: MomentumScoreParamsType): Promise<MomentumScoreResponse>;
	sync(params: MomentumSyncParamsType): Promise<MomentumSyncResponse>;
	status(params: MomentumStatusParamsType): Promise<MomentumStatusResponse>;
}

export function createMomentumMethods(call: CallFn): MomentumMethods {
	return {
		refresh: (params) => call<MomentumRefreshResponse>("momentum/refresh", params),
		score: (params) => call<MomentumScoreResponse>("momentum/score", params),
		sync: (params) => call<MomentumSyncResponse>("momentum/sync", params),
		status: (params) => call<MomentumStatusResponse>("momentum/status", params),
	};
}
