/**
 * Intelligence method wrappers
 *
 * @module @vreko/local-service-client/methods/intelligence
 */

import type {
	IntelligenceCaptureParamsType,
	IntelligenceOutcomeParamsType,
	IntelligenceSnapshot,
	IntelligenceSnapshotParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface IntelligenceCaptureResponse {
	captured: boolean;
	domain: string;
	type: string;
	error?: string;
}

export interface IntelligenceOutcomeResponse {
	recorded: boolean;
	patternId: string;
	outcome: string;
	notes?: string;
}

export interface IntelligenceMethods {
	capture(params: IntelligenceCaptureParamsType): Promise<IntelligenceCaptureResponse>;
	outcome(params: IntelligenceOutcomeParamsType): Promise<IntelligenceOutcomeResponse>;
	snapshot(
		params: IntelligenceSnapshotParamsType,
	): Promise<IntelligenceSnapshot | { error: string; workspace: string }>;
}

export function createIntelligenceMethods(call: CallFn): IntelligenceMethods {
	return {
		capture: (params) => call<IntelligenceCaptureResponse>("intelligence/capture", params),
		outcome: (params) => call<IntelligenceOutcomeResponse>("intelligence/outcome", params),
		snapshot: (params) => call<IntelligenceSnapshot>("intelligence/snapshot", params),
	};
}
