/**
 * Protection policy method wrappers
 *
 * @module @vreko/local-service-client/methods/protection
 */

import type {
	ProtectionDecision,
	ProtectionEvaluateParamsType,
	ProtectionLevel,
	ProtectionLevelsParamsType,
	ProtectionSetParamsType,
} from "../types.js";
import type { CallFn } from "./health.js";

/**
 * Protection levels response
 */
export interface ProtectionLevelsResponse {
	/** Map of file path to protection level */
	levels: Record<string, ProtectionLevel>;
}

/**
 * Protection set response
 */
export interface ProtectionSetResponse {
	/** File path */
	filePath: string;
	/** New protection level */
	level: ProtectionLevel;
	/** Whether this is a custom rule (vs automatic) */
	isCustom: boolean;
}

/**
 * Protected file entry from daemon list
 */
export interface ProtectedFileDaemonEntry {
	pattern: string;
	level: ProtectionLevel;
	[key: string]: unknown;
}

/**
 * Protection methods namespace
 */
export interface ProtectionMethods {
	/**
	 * Evaluate protection policy for a file
	 */
	evaluate(params: ProtectionEvaluateParamsType): Promise<ProtectionDecision>;

	/**
	 * Get protection levels for multiple files
	 */
	levels(params: ProtectionLevelsParamsType): Promise<ProtectionLevelsResponse>;

	/**
	 * Set custom protection level for a file/pattern
	 */
	set(params: ProtectionSetParamsType): Promise<ProtectionSetResponse>;

	/**
	 * List daemon-managed protected files for a workspace
	 */
	listDaemon(params: { workspace: string }): Promise<ProtectedFileDaemonEntry[]>;
}

/**
 * Create protection methods namespace
 */
export function createProtectionMethods(call: CallFn): ProtectionMethods {
	return {
		evaluate: (params) => call<ProtectionDecision>("protection/evaluate", params),
		levels: (params) => call<ProtectionLevelsResponse>("protection/levels", params),
		set: (params) => call<ProtectionSetResponse>("protection/set", params),
		listDaemon: (params) => call<ProtectedFileDaemonEntry[]>("protection/list-daemon", params),
	};
}
