/**
 * Watch (file watcher) method wrappers
 *
 * @module @vreko/local-service-client/methods/watch
 */

import type {
	WatchFileChangedParamsType,
	WatchSubscribeParamsType,
	WatchUnsubscribeParamsType,
} from "@vreko/contracts/local-service";
import type { CallFn } from "./health.js";

export interface WatchSubscribeResponse {
	subscribed: boolean;
	patterns: string[];
}

export interface WatchUnsubscribeResponse {
	unsubscribed: boolean;
}

export interface WatchFileChangedResponse {
	received: boolean;
	file: string;
	timestamp: number;
}

export interface WatchMethods {
	subscribe(params: WatchSubscribeParamsType): Promise<WatchSubscribeResponse>;
	unsubscribe(params: WatchUnsubscribeParamsType): Promise<WatchUnsubscribeResponse>;
	fileChanged(params: WatchFileChangedParamsType): Promise<WatchFileChangedResponse>;
}

export function createWatchMethods(call: CallFn): WatchMethods {
	return {
		subscribe: (params) => call<WatchSubscribeResponse>("watch/subscribe", params),
		unsubscribe: (params) => call<WatchUnsubscribeResponse>("watch/unsubscribe", params),
		fileChanged: (params) => call<WatchFileChangedResponse>("watch/file-changed", params),
	};
}
